macro_rules! shebang {
    () => {
        # [doc = ""] pub mod shebang { use std :: { ffi :: OsString , path :: PathBuf } ; use bstr :: { BStr , ByteSlice } ; # [doc = " Parse `buf` to extract all shebang information."] pub fn parse (buf : & BStr) -> Option < Data > { let mut line = buf . lines () . next () ? ; line = line . strip_prefix (b"#!") ? ; let slash_idx = line . rfind_byteset (br"/\") ? ; Some (match line [slash_idx ..] . find_byte (b' ') { Some (space_idx) => { let space = slash_idx + space_idx ; Data { interpreter : gix_path :: from_byte_slice (line [.. space] . trim ()) . to_owned () , args : line . get (space + 1 ..) . and_then (| mut r | { r = r . trim () ; if r . is_empty () { return None ; } match r . as_bstr () . to_str () { Ok (args) => shell_words :: split (args) . ok () . map (| args | args . into_iter () . map (Into :: into) . collect ()) , Err (_) => Some (vec ! [gix_path :: from_byte_slice (r) . to_owned () . into ()]) , } }) . unwrap_or_default () , } } None => Data { interpreter : gix_path :: from_byte_slice (line . trim ()) . to_owned () , args : Vec :: new () , } , }) } # [doc = " Shebang information as [parsed](parse()) from a buffer that should contain at least one line."] # [doc = ""] # [doc = " ### Deviation"] # [doc = ""] # [doc = " According to the [shebang documentation](https://en.wikipedia.org/wiki/Shebang_(Unix)), it will only consider"] # [doc = " the path of the executable, along with the arguments as the consecutive portion after the space that separates"] # [doc = " them. Argument splitting would then have to be done elsewhere, probably in the kernel."] # [doc = ""] # [doc = " To make that work without the kernel, we perform the splitting while Git just ignores options."] # [doc = " For now it seems more compatible to not ignore options, but if it is important this could be changed."] # [derive (Debug , Clone , PartialEq , Eq , Ord , PartialOrd , Hash)] pub struct Data { # [doc = " The interpreter to run."] pub interpreter : PathBuf , # [doc = " The remainder of the line past the space after `interpreter`, without leading or trailing whitespace,"] # [doc = " as pre-split arguments just like a shell would do it."] # [doc = " Note that we accept that illformed UTF-8 will prevent argument splitting."] pub args : Vec < OsString > , } }
    };
}

shebang!();